pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    function testFuzz_property(address from, uint256 tosLen) public {
        uint256 len = bound(tosLen, 0, 8);
        vm.assume(len > 0);

        Reverter rev = new Reverter();

        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) tos[i] = address(rev);

        bool ok;
        try c.transfer(from, address(rev), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}
